// NODE: Plan Input | Mode: Run Once for Each Item | Language: JavaScript
const REVIEW_ALL = true; // true = ask for approval on EVERY note (use for the demo)
const MAX_ROUNDS = 2;     // most back-and-forth rounds per note

const j = $json;
const prior = j.prior_plan ?? null;
const feedback = j.feedback ?? '';

let input = 'CREATOR NOTE:\n' + j.raw_note;
if (prior) input += '\n\nYOUR PREVIOUS PLAN:\n' + JSON.stringify(prior, null, 2);
if (feedback) input += '\n\nCREATOR FEEDBACK (apply it, keep everything they did not change):\n' + feedback;

return {
  json: {
    submission_id: j.submission_id,
    creator_name: j.creator_name ?? j.creator?.name ?? '',
    creator_email: j.creator_email ?? j.creator?.email ?? '',
    raw_note: j.raw_note,
    round: j.round ?? 0,
    feedback,
    approved: j.approved ?? false,
    timed_out: j.timed_out ?? false,
    prior_plan: prior,
    review_all: REVIEW_ALL,
    max_rounds: MAX_ROUNDS,
    input_text: input,
  },
};

// NODE: Map Plan | Mode: Run Once for Each Item | Language: JavaScript
const state = $('Plan Input').last().json; // batch size is 1, so the last run is this note
const ai = $json.output ?? {};
const FORMATS = ['youtube_long', 'short_video', 'blog_post', 'linkedin_post'];
const clean = (v) => (typeof v === 'string' ? v.trim() : '');

let plan;
let flagged;
if (state.approved && state.prior_plan) {
  plan = state.prior_plan;            // you approved it: keep it exactly
  flagged = state.timed_out === true; // a timeout is not an approval
} else {
  plan = {
    anchor_format: clean(ai.anchor_format).toLowerCase().replace(/[^a-z_]/g, ''),
    anchor_title: clean(ai.anchor_title),
    anchor_hook: clean(ai.anchor_hook),
    core_angle: clean(ai.core_angle),
    audience: clean(ai.audience),
    tone: clean(ai.tone),
    hook_short_video: clean(ai.hook_short_video),
    hook_linkedin: clean(ai.hook_linkedin),
    hook_carousel: clean(ai.hook_carousel),
    hook_blog: clean(ai.hook_blog),
  };
  const missing = [];
  if (!FORMATS.includes(plan.anchor_format)) missing.push('format');
  if (!plan.anchor_title) missing.push('title');
  if (!plan.core_angle) missing.push('angle');
  const aiFlag = ai.needs_clarification === true || String(ai.needs_clarification).toLowerCase() === 'true';
  flagged = aiFlag || missing.length > 0;
  plan._missing = missing;
  plan._question = clean(ai.question);
}

const roundsLeft = state.round < state.max_rounds;
const wantsInput = !state.approved && (flagged || state.review_all);
const needs_input = wantsInput && roundsLeft;
const needs_review = flagged && !needs_input; // still unresolved, nobody left to ask

const question =
  plan._question ||
  (plan._missing && plan._missing.includes('format')
    ? 'Which format should the main piece be: a long YouTube video, a short video, a blog post, or a LinkedIn post?'
    : 'Anything you want changed in this plan? Reply OK to approve.');

return {
  json: {
    submission_id: state.submission_id,
    creator_name: state.creator_name,
    creator_email: state.creator_email,
    raw_note: state.raw_note,
    round: state.round,
    max_rounds: state.max_rounds,
    plan,
    question,
    needs_input,
    needs_review,
  },
};

const s = $('Map Plan').last().json;
const d = $json.data ?? {};

const reply = String(
  d.text ?? Object.values(d)[0] ?? ''
).trim();

const timedOut = reply === '';

const approved =
  timedOut ||
  /^(ok|okay|approve|approved|yes|y|looks good|lgtm|go|ship it)[\s.!]*$/i.test(reply);

return {
  json: {
    submission_id: s.submission_id,
    creator_name: s.creator_name,
    creator_email: s.creator_email,
    raw_note: s.raw_note,
    round: timedOut ? s.max_rounds : s.round + 1,
    feedback: approved ? '' : reply,
    approved,
    timed_out: timedOut,
    prior_plan: s.plan,
  },
};

const rows = $input.all().map(item => item.json);
if (!rows.length) return [];

const escape = value => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const groups = new Map();

for (const row of rows) {
  if (!row.submission_id || !row.piece_id) {
    throw new Error('Digest input is missing submission_id or piece_id.');
  }

  if (!groups.has(row.submission_id)) {
    groups.set(row.submission_id, []);
  }

  groups.get(row.submission_id).push(row);
}

const isReview = piece =>
  String(piece.status ?? '').trim().toLowerCase() === 'needs review';

const badge = review => `
  <span style="
    display:inline-block;
    padding:4px 9px;
    border-radius:4px;
    font-size:12px;
    font-weight:bold;
    background:${review ? '#fff3d6' : '#e8f4f1'};
    color:${review ? '#805600' : '#25695e'};
  ">
    ${review ? 'Needs review' : 'Planned'}
  </span>
`;

const sections = [...groups.entries()].map(([id, pieces]) => {
  const anchor = pieces.find(
    piece => String(piece.role).toLowerCase() === 'anchor'
  ) || pieces[0];

  const cards = pieces.map(piece => `
    <table role="presentation" width="100%" cellpadding="0"
      cellspacing="0" style="
        border:1px solid #dde7e4;
        border-radius:6px;
        margin-bottom:12px;
        background:#ffffff;
      ">
      <tr>
        <td style="padding:18px;">
          <p style="
            margin:0 0 8px;
            font-size:12px;
            font-weight:bold;
            color:#35786d;
          ">
            ${escape(piece.role)}
          </p>

          <h3 style="
            margin:0 0 7px;
            font-size:17px;
            line-height:1.4;
            color:#243733;
          ">
            ${escape(piece.title)}
          </h3>

          <p style="
            margin:0 0 14px;
            font-size:14px;
            color:#65736f;
          ">
            ${escape(piece.platform)} &middot; ${escape(piece.format)}
          </p>

          <p style="
            margin:0 0 5px;
            font-size:14px;
            color:#374741;
          ">
            <strong>Produce by:</strong> ${escape(piece.produce_by)}
          </p>

          <p style="
            margin:0 0 14px;
            font-size:14px;
            color:#374741;
          ">
            <strong>Publish on:</strong> ${escape(piece.publish_on)}
          </p>

          ${isReview(piece)
            ? badge(true)
            : `<span style="
                display:inline-block;
                padding:4px 9px;
                border-radius:4px;
                background:#e8f4f1;
                color:#25695e;
                font-size:12px;
                font-weight:bold;
              ">${escape(piece.status || 'Status not provided')}</span>`
          }
        </td>
      </tr>
    </table>
  `).join('');

  return `
    <h2 style="
      margin:28px 0 8px;
      font-size:20px;
      line-height:1.4;
      color:#243733;
    ">
      ${escape(anchor.title)}
    </h2>

    <p style="
      margin:0 0 12px;
      font-size:13px;
      color:#65736f;
    ">
      ${escape(anchor.creator)} &middot; ${escape(id)}
    </p>

    ${pieces.some(isReview)
      ? `<p style="margin:0 0 14px;">${badge(true)}</p>`
      : ''
    }

    ${cards}
  `;
}).join('');

const summary = `${rows.length} pieces planned from ${groups.size} notes`;
const reviewCount = rows.filter(isReview).length;

return [{
  json: {
    subject: `Atomizer: ${summary}`,
    html: `
      <!DOCTYPE html>
      <html>
      <head>
        <meta name="viewport" content="width=device-width, initial-scale=1">
      </head>
      <body style="
        margin:0;
        padding:0;
        background:#f4f7f6;
        font-family:Arial,Helvetica,sans-serif;
        color:#243733;
      ">
        <table role="presentation" width="100%"
          cellpadding="0" cellspacing="0">
          <tr>
            <td align="center" style="padding:20px 12px;">
              <table role="presentation" width="100%"
                cellpadding="0" cellspacing="0" style="
                  max-width:600px;
                  background:#ffffff;
                  border-top:4px solid #35786d;
                ">
                <tr>
                  <td style="padding:26px 20px;">
                    <p style="
                      margin:0 0 20px;
                      font-size:12px;
                      font-weight:bold;
                      letter-spacing:2px;
                      color:#35786d;
                    ">ATOMIZER</p>

                    <h1 style="
                      margin:0 0 10px;
                      font-size:28px;
                      line-height:1.2;
                    ">Your content plan</h1>

                    <p style="
                      margin:0;
                      font-size:15px;
                      line-height:1.6;
                      color:#65736f;
                    ">${escape(summary)}.</p>

                    ${reviewCount
                      ? `<p style="
                          margin:14px 0 0;
                          padding:12px;
                          background:#fff8e8;
                          color:#805600;
                          font-size:14px;
                          line-height:1.5;
                        ">
                          ${reviewCount} ${reviewCount === 1 ? 'piece needs' : 'pieces need'}
                          review before production.
                        </p>`
                      : ''
                    }

                    ${sections}

                    <p style="
                      margin:26px 0 0;
                      padding-top:16px;
                      border-top:1px solid #dde7e4;
                      font-size:12px;
                      line-height:1.6;
                      color:#65736f;
                    ">
                      Production dates are for preparing each piece.
                      Publishing dates are for releasing it.
                    </p>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>
      </body>
      </html>
    `
  }
}];

const incoming = $('Split Out').all()
  .map(item => item.json);

const existingRows = $input.all()
  .map(item => item.json);

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const existingIds = new Set(
  existingRows
    .map(row => normalize(row.submission_id))
    .filter(Boolean)
);

const seenInBatch = new Set();
const newNotes = [];

for (const note of incoming) {
  const submissionId = normalize(note.submission_id);

  if (!submissionId) {
    throw new Error('Incoming note is missing submission_id');
  }

  if (!note.raw_note || !String(note.raw_note).trim()) {
    throw new Error(
      `Missing raw_note for ${note.submission_id}`
    );
  }

  if (!note.creator?.email) {
    throw new Error(
      `Missing creator email for ${note.submission_id}`
    );
  }

  const creatorEmail = normalize(note.creator.email);

  // Composite identity avoids collisions between creators.
  const key = `${creatorEmail}::${submissionId}`;

  // Existing Content Log rows may repeat the same submission
  // across several content pieces.
  const alreadyProcessed = existingRows.some(row => {
    const sameSubmission =
      normalize(row.submission_id) === submissionId;

    const storedEmail = normalize(
      row.creator_email ?? ''
    );

    // The Build Plan's Content Log has creator name,
    // but does not require creator_email.
    // Therefore submission_id remains the fallback key.
    return sameSubmission &&
      (!storedEmail || storedEmail === creatorEmail);
  });

  if (alreadyProcessed || seenInBatch.has(key)) {
    continue;
  }

  seenInBatch.add(key);
  newNotes.push({ json: note });
}

return newNotes;

/*
 * ATOMIZER - BUILD PIECES
 * Mode: Run Once for All Items
 * Timezone: Asia/Manila
 *
 * Converts AI content plans into scheduled pieces.
 * No external writes occur in this node.
 */

const plans = $input.all().map(item => item.json);

const TZ = 'Asia/Manila';
const DAY = 86400000;

// Calendar-date arithmetic in UTC avoids local DST shifts.
function dateAfter(days) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  const values = Object.fromEntries(
    parts.map(p => [p.type, p.value])
  );

  const midnight = Date.UTC(
    Number(values.year),
    Number(values.month) - 1,
    Number(values.day)
  );

  return new Date(midnight + days * DAY)
    .toISOString().slice(0, 10);
}

// Philippine Standard Time is UTC+08:00.
function calendarTime(date, hour) {
  return `${date}T${String(hour).padStart(2, '0')}:00:00+08:00`;
}

const RULES = {
  youtube_long: [
    ['A', 'Anchor', 'YouTube', 'Long-form video', 4, 7, 'anchor_title'],
    ['S1', 'Spin-off', 'TikTok / Reels', 'Short vertical video', 7, 8, 'hook_short_video'],
    ['S2', 'Spin-off', 'LinkedIn', 'Text post', 8, 9, 'hook_linkedin'],
    ['S3', 'Spin-off', 'Instagram', 'Carousel', 9, 10, 'hook_carousel'],
    ['S4', 'Spin-off', 'Blog', 'Article', 10, 11, 'hook_blog']
  ],
  short_video: [
    ['A', 'Anchor', 'TikTok / Reels', 'Short vertical video', 1, 2, 'anchor_title'],
    ['S1', 'Spin-off', 'LinkedIn', 'Text post', 2, 3, 'hook_linkedin']
  ],
  blog_post: [
    ['A', 'Anchor', 'Blog', 'Article', 3, 5, 'anchor_title'],
    ['S1', 'Spin-off', 'LinkedIn', 'Text post', 5, 6, 'hook_linkedin'],
    ['S2', 'Spin-off', 'Instagram', 'Carousel', 6, 7, 'hook_carousel']
  ],
  linkedin_post: [
    ['A', 'Anchor', 'LinkedIn', 'Text post', 1, 2, 'anchor_title'],
    ['S1', 'Spin-off', 'TikTok / Reels', 'Short vertical video', 2, 4, 'hook_short_video']
  ]
};

const results = [];

for (const data of plans) {
  const plan = data.plan ?? {};
  const format = plan.anchor_format;
  const rules = RULES[format];

  if (!rules) {
    throw new Error(
      `Unsupported anchor format for ${data.submission_id}: ${format}`
    );
  }

  if (!data.submission_id || !data.creator_email) {
    throw new Error('Missing submission identity fields');
  }

  const review = data.needs_review === true;

  for (const [
    suffix, role, platform, pieceFormat,
    productionOffset, publishOffset, titleField
  ] of rules) {

    const pieceId = `${data.submission_id}-${suffix}`;
    const produceBy = dateAfter(productionOffset);
    const publishOn = dateAfter(publishOffset);

    const isAnchor = role === 'Anchor';

    const title = isAnchor
      ? (plan.anchor_title || 'Untitled content')
      : (plan[titleField] || plan.anchor_title || 'Untitled content');

    const hook = isAnchor
      ? (plan.anchor_hook || '')
      : (plan[titleField] || plan.anchor_hook || '');

    results.push({
      json: {
        piece_id: pieceId,
        submission_id: data.submission_id,
        family_id: data.family_id ?? '',
        similar_family_id: data.similar_family_id ?? '',
        similarity_status: data.similarity_status ?? '',
        match_confidence: data.match_confidence ?? '',
        decision: data.decision ?? '',
        angle_update: data.angle_update ?? '',
        creator: data.creator_name,
        creator_email: data.creator_email,

        role,
        platform,
        format: pieceFormat,
        title,
        hook,

        audience: plan.audience || '',
        angle: plan.core_angle || '',

        status: review ? 'Needs review' : 'Planned',

        produce_by: produceBy,
        publish_on: publishOn,

        start_time: calendarTime(produceBy, 9),
        end_time: calendarTime(produceBy, 10),
        timezone: TZ,

        event_title: `[Atomizer] ${role}: ${title}`,
        event_description: [
          `Content ID: ${pieceId}`,
          `Creator: ${data.creator_name}`,
          `Platform: ${platform}`,
          `Format: ${pieceFormat}`,
          `Production deadline: ${produceBy}`,
          `Publish on: ${publishOn}`,
          `Angle: ${plan.core_angle || ''}`,
          `Status: ${review ? 'Needs review' : 'Planned'}`
        ].join('\n'),

        rounds: data.round ?? 0,
        created_at: dateAfter(0)
      }
    });
  }
}

return results;

/*
 * ATOMIZER - ROW FOR SHEET
 * Mode: Run Once for All Items
 *
 * Maps created Google Calendar events
 * back to their original content pieces.
 */

const pieces = $('Build Pieces').all()
  .map(item => item.json);

const events = $input.all()
  .map(item => item.json);

if (pieces.length !== events.length) {
  throw new Error(
    `Count mismatch: ${pieces.length} pieces, ` +
    `${events.length} Calendar events`
  );
}

const rows = [];

for (let i = 0; i < pieces.length; i++) {
  const piece = pieces[i];
  const event = events[i];

  if (!event.id) {
    throw new Error(
      `Missing Calendar event ID for ${piece.piece_id}`
    );
  }

  // Verify event identity before mapping by position.
  // This prevents silently attaching an unrelated event.
  if (event.summary !== piece.event_title) {
    throw new Error(
      `Calendar event mismatch for ${piece.piece_id}`
    );
  }

  rows.push({
    json: {
      piece_id: piece.piece_id,
      submission_id: piece.submission_id,
      family_id: piece.family_id ?? '',
      similar_family_id: piece.similar_family_id ?? '',
      similarity_status: piece.similarity_status ?? '',
      match_confidence: piece.match_confidence ?? '',
      decision: piece.decision ?? '',
      angle_update: piece.angle_update ?? '',
      creator: piece.creator,
      role: piece.role,
      platform: piece.platform,
      format: piece.format,
      title: piece.title,
      hook: piece.hook,
      audience: piece.audience,
      angle: piece.angle,
      status: piece.status,
      produce_by: piece.produce_by,
      publish_on: piece.publish_on,
      calendar_event_id: event.id,
      event_link: event.htmlLink ?? '',
      rounds: piece.rounds,
      created_at: piece.created_at
    }
  });
}

return rows;

const rows = $input.all().map(item => item.json);

const families = new Map();

for (const row of rows) {
  const familyId = String(row.family_id ?? "").trim();

  // Ignore rows without a valid family identifier.
  if (!familyId) continue;

  if (!families.has(familyId)) {
    families.set(familyId, {
      family_id: familyId,
      submission_id: row.submission_id,
      creator_email: row.creator_email,
      angles: []
    });
  }

  families.get(familyId).angles.push({
    title: row.title,
    summary: row.summary,
    platform: row.platform,
    format: row.format,
    theme: row.theme
  });
}

return Array.from(families.values()).map(family => ({
  json: {
    ...family,
    angle_count: family.angles.length
  }
}));

const items = $input.all();

return items.map(item => {
  const data = item.json;
  const plan = data.plan ?? {};

  const title = String(
    plan.anchor_title ?? ''
  ).trim();

  const summary = String(
    plan.core_angle ?? ''
  ).trim();

  const theme = String(
    plan.audience ?? ''
  ).trim();

  return {
    json: {
      ...data,

      title,
      summary,
      theme,

      format: plan.anchor_format ?? '',

      comparison_text: [
        title,
        summary,
        theme
      ].filter(Boolean).join(' | '),

      comparison_status:
        title && summary
          ? 'Ready for comparison'
          : 'Insufficient information'
    }
  };
});

const records = $input.all().map(item => item.json);

// Identify the incoming idea.
const incomingIdeas = records.filter(
  record => typeof record.comparison_text === "string"
);

// Identify existing content families.
const existingFamilies = records.filter(
  record =>
    typeof record.family_id === "string" &&
    Array.isArray(record.angles)
);

// Validate that exactly one incoming idea is present.
if (incomingIdeas.length !== 1) {
  throw new Error(
    `Expected 1 incoming idea, found ${incomingIdeas.length}`
  );
}

const incoming = incomingIdeas[0];

// Only compare against families belonging to this creator.
const eligibleFamilies = existingFamilies.filter(
  family =>
    String(family.creator_email ?? "").trim().toLowerCase() ===
    String(incoming.creator_email ?? "").trim().toLowerCase()
);

return [{
  json: {
    incoming_idea: incoming,
    existing_families: eligibleFamilies,
    incoming_count: incomingIdeas.length,
    family_count: eligibleFamilies.length,
    validation_status:
      incoming.comparison_status === "Ready for comparison"
        ? "Validated"
        : "Insufficient information"
  }
}];

const data = $input.first().json;

if (data.validation_status !== "Validated") {
  return [{
    json: {
      ...data,
      candidates: [],
      candidate_count: 0,
      preparation_status: "Needs clarification"
    }
  }];
}

const incoming = data.incoming_idea;
const families = data.existing_families ?? [];

const stopwords = new Set([
  "the", "and", "for", "with", "from", "this",
  "that", "into", "about", "your", "you",
  "are", "was", "were", "have", "has",
  "how", "why", "what", "its", "our"
]);

function tokenize(text) {
  return new Set(
    String(text ?? "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .split(/\s+/)
      .filter(word =>
        word.length > 2 && !stopwords.has(word)
      )
  );
}

function overlapScore(a, b) {
  const tokensA = tokenize(a);
  const tokensB = tokenize(b);

  if (!tokensA.size || !tokensB.size) return 0;

  const intersection = [...tokensA]
    .filter(word => tokensB.has(word)).length;

  const union = new Set([...tokensA, ...tokensB]).size;

  return Number((intersection / union).toFixed(4));
}

const candidates = families.map(family => {
  const angleScores = (family.angles ?? []).map(angle => {
    const text = [
      angle.title,
      angle.summary,
      angle.theme
    ].filter(Boolean).join(" | ");

    return overlapScore(incoming.comparison_text, text);
  });

  const keywordScore = angleScores.length
    ? Math.max(...angleScores)
    : 0;

  return {
    family_id: family.family_id,
    angle_count: family.angle_count,
    angles: family.angles,
    keyword_score: keywordScore
  };
});

candidates.sort(
  (a, b) => b.keyword_score - a.keyword_score
);

return [{
  json: {
    incoming_idea: incoming,
    candidates,
    candidate_count: candidates.length,
    preparation_status: "Ready for semantic comparison"
  }
}];

