const aiResponse = $input.first().json.output;

const source = $("Prepare Similarity Candidates")
  .first().json;

const incoming = source.incoming_idea;
const candidates = source.candidates ?? [];

const candidateMap = new Map(
  candidates.map(candidate => [
    candidate.family_id,
    candidate
  ])
);

const errors = [];
const validatedMatches = [];
const seenIds = new Set();

if (!Array.isArray(aiResponse?.matches)) {
  errors.push("AI response has no valid matches array");
} else {
  for (const match of aiResponse.matches) {
    const id = match?.family_id;
    const candidate = candidateMap.get(id);

    if (!candidate) {
      errors.push(`Unknown family ID: ${id}`);
      continue;
    }

    if (seenIds.has(id)) {
      errors.push(`Duplicate family ID: ${id}`);
      continue;
    }

    seenIds.add(id);

    if (
      typeof match.semantic_score !== "number" ||
      !Number.isFinite(match.semantic_score) ||
      match.semantic_score < 0 ||
      match.semantic_score > 1
    ) {
      errors.push(`Invalid semantic score: ${id}`);
      continue;
    }

    if (
      typeof match.reason !== "string" ||
      !match.reason.trim()
    ) {
      errors.push(`Missing explanation: ${id}`);
      continue;
    }

    if (
      !Array.isArray(match.suggested_angles) ||
      match.suggested_angles.length < 2 ||
      !match.suggested_angles.every(
        angle =>
          typeof angle === "string" &&
          angle.trim().length > 0
      )
    ) {
      errors.push(`Invalid suggested angles: ${id}`);
      continue;
    }

    validatedMatches.push({
      family_id: id,
      keyword_score: candidate.keyword_score,
      semantic_score: match.semantic_score,
      reason: match.reason.trim(),
      suggested_angles: match.suggested_angles
        .map(angle => angle.trim())
    });
  }
}

for (const candidate of candidates) {
  if (!seenIds.has(candidate.family_id)) {
    errors.push(
      `Missing candidate: ${candidate.family_id}`
    );
  }
}

validatedMatches.sort(
  (a, b) => b.semantic_score - a.semantic_score
);

return [{
  json: {
    incoming_idea: incoming,
    validated_matches:
      errors.length === 0 ? validatedMatches : [],
    match_count:
      errors.length === 0 ? validatedMatches.length : 0,
    validation_status:
      errors.length === 0
        ? "Passed"
        : "Failed",
    validation_errors: errors
  }
}];

const data = $input.first().json;
const incoming = data.incoming_idea ?? {};
const matches = data.validated_matches ?? [];

// Existing family records from the earlier lookup.
const existingFamilies =
  $("Group Existing Families")
    .all()
    .map(item => item.json);

const threshold = 0.80;

const submissionId =
  String(incoming.submission_id ?? "").trim();

const creatorEmail =
  String(incoming.creator_email ?? "")
    .trim()
    .toLowerCase();

// Check whether this submission already exists.
const duplicateFamily = existingFamilies.find(family =>
  String(family.submission_id ?? "").trim() === submissionId &&
  String(family.creator_email ?? "")
    .trim()
    .toLowerCase() === creatorEmail
);

const bestMatch = matches.length
  ? [...matches].sort(
      (a, b) => b.semantic_score - a.semantic_score
    )[0]
  : null;

let decision;
let similarityStatus;
let similarFamilyId = "";
let matchConfidence = null;
let suggestedAngles = [];
let reason = "";
let shouldCreateFamily = false;

if (data.validation_status !== "Passed") {
  decision = "Manual review required";
  similarityStatus = "Validation failed";
  reason = (data.validation_errors ?? []).join("; ");

} else if (!submissionId || !creatorEmail) {
  decision = "Manual review required";
  similarityStatus = "Missing identity fields";
  reason = "Submission ID or creator email is missing";

} else if (duplicateFamily) {
  decision = "Existing submission detected";
  similarityStatus = "Duplicate submission";
  similarFamilyId = duplicateFamily.family_id;
  reason = "This submission ID already exists for this creator";

} else if (
  bestMatch &&
  bestMatch.semantic_score >= threshold
) {
  decision = "New family created";
  similarityStatus = "Similar idea flagged";
  similarFamilyId = bestMatch.family_id;
  matchConfidence = bestMatch.semantic_score;
  suggestedAngles = bestMatch.suggested_angles;
  reason = bestMatch.reason;
  shouldCreateFamily = true;

} else {
  decision = "New family created";
  similarityStatus = "No significant similarity";
  matchConfidence = bestMatch?.semantic_score ?? null;
  reason = bestMatch
    ? "No existing family reached the similarity threshold"
    : "No existing family matches were available";
  shouldCreateFamily = true;
}

return [{
  json: {
    ...incoming,
    similar_family_id: similarFamilyId,
    similarity_status: similarityStatus,
    match_confidence: matchConfidence,
    decision,
    angle_update: suggestedAngles.join(" | "),
    decision_reason: reason,
    should_create_family: shouldCreateFamily,
    similarity_threshold: threshold,
    family_id: "",
    decision_status: "Evaluated"
  }
}];

const decision = $input.first().json;

const existingFamilies = $("Group Existing Families")
  .all()
  .map(item => item.json);

if (decision.should_create_family !== true) {
  return [{
    json: {
      ...decision,
      family_id: "",
      family_creation_status: "Skipped"
    }
  }];
}

// Find the highest existing numeric family ID.
const existingNumbers = existingFamilies
  .map(family => {
    const match = String(family.family_id ?? "")
      .match(/^FAM-(\d+)$/);

    return match ? Number(match[1]) : null;
  })
  .filter(number =>
    Number.isSafeInteger(number) && number >= 0
  );

const highestId = existingNumbers.length
  ? Math.max(...existingNumbers)
  : 0;

const newFamilyId =
  `FAM-${String(highestId + 1).padStart(4, "0")}`;

return [{
  json: {
    ...decision,
    family_id: newFamilyId,
    decision: "New family proposed",
    family_creation_status: "Pending persistence"
  }
}];

const items = $input.all();

const requiredFields = [
  "submission_id",
  "creator_email",
  "title",
  "summary",
  "family_id"
];

return items.map(item => {
  const data = item.json;

  if (data.should_create_family !== true) {
    throw new Error("Family creation is not authorized");
  }

  if (data.family_creation_status !== "Pending persistence") {
    throw new Error("Family is not awaiting persistence");
  }

  for (const field of requiredFields) {
    if (!String(data[field] ?? "").trim()) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  if (!/^FAM-\d{4,}$/.test(data.family_id)) {
    throw new Error("Invalid family ID format");
  }

  if (
    data.similar_family_id &&
    data.similar_family_id === data.family_id
  ) {
    throw new Error("A family cannot reference itself");
  }

  return {
    json: {
      submission_id: data.submission_id,
      created_at: new Date().toISOString(),
      creator_name: data.creator_name ?? "",
      creator_email: data.creator_email,
      submitted_at: data.submitted_at ?? "",
      title: data.title,
      summary: data.summary,
      platform: data.platform ?? "",
      format: data.format ?? "",
      theme: data.theme ?? "",
      next_action: data.next_action ?? "",
      priority: data.priority ?? "",
      needs_clarification: data.needs_clarification ?? "",
      status: "Pending review",
      calendar_event_id: "",
      family_id: data.family_id,
      similar_family_id: data.similar_family_id ?? "",
      similarity_status: data.similarity_status ?? "",
      match_confidence: data.match_confidence ?? "",
      decision: "New family proposed",
      angle_update: data.angle_update ?? ""
    }
  };
});

const proposed = $("Prepare Family Record").first().json;

const existingRows = $input.all().map(item => item.json);

const errors = [];

const normalize = value =>
  String(value ?? "").trim().toLowerCase();

const familyId = String(proposed.family_id ?? "").trim();
const submissionId = normalize(proposed.submission_id);
const creatorEmail = normalize(proposed.creator_email);

// Validate required identifiers.
if (!/^FAM-\d{4,}$/.test(familyId)) {
  errors.push("Invalid or missing family ID");
}

if (!submissionId) {
  errors.push("Missing submission ID");
}

if (!creatorEmail) {
  errors.push("Missing creator email");
}

// Check for an existing family ID.
const familyCollision = existingRows.some(row =>
  normalize(row.family_id) === normalize(familyId)
);

if (familyCollision) {
  errors.push(`Family ID already exists: ${familyId}`);
}

// Check for a repeated submission by the same creator.
const submissionCollision = existingRows.some(row =>
  normalize(row.submission_id) === submissionId &&
  normalize(row.creator_email) === creatorEmail
);

if (submissionCollision) {
  errors.push(
    "Submission already exists for this creator"
  );
}

// Verify the creation decision.
const decision = $("Assign New Family ID").first().json;

if (decision.should_create_family !== true) {
  errors.push("Family creation was not authorized");
}

if (decision.family_id !== familyId) {
  errors.push("Proposed family ID does not match decision");
}

if (
  decision.family_creation_status !==
  "Pending persistence"
) {
  errors.push("Invalid family creation status");
}

const writeAllowed = errors.length === 0;

return [{
  json: {
    ...proposed,
    write_allowed: writeAllowed,
    uniqueness_status: writeAllowed
      ? "Passed"
      : "Blocked",
    uniqueness_errors: errors,
    existing_rows_checked: existingRows.length,
    family_id_collision: familyCollision,
    submission_collision: submissionCollision
  }
}];

const savedRows = $input.all();
const original = $("Assign New Family ID").first().json;

if (!original.plan?.anchor_format) {
  throw new Error("Original content plan is missing");
}

return savedRows.map(item => {
  const saved = item.json;

  if (saved.submission_id !== original.submission_id) {
    throw new Error("Submission ID mismatch after persistence");
  }

  return {
    json: {
      ...original,
      ...saved,
      plan: original.plan,
      family_id: saved.family_id || original.family_id
    }
  };
});
